def min_window(s: str, t: str) -> str:
    from collections import Counter

    if not s or not t:
        return ''

    t_count = Counter(t)
    required = len(t_count)
    formed = 0
    window_count = {}
    left = 0
    right = 0
    ans = float("inf"), None, None

    while right < len(s):
        character = s[right]
        window_count[character] = window_count.get(character, 0) + 1

        if character in t_count and window_count[character] == t_count[character]:
            formed += 1

        while left <= right and formed == required:
            character = s[left]
            if right - left + 1 < ans[0]:
                ans = (right - left + 1, left, right)
            window_count[character] -= 1
            if character in t_count and window_count[character] < t_count[character]:
                formed -= 1
            left += 1

        right += 1

    return '' if ans[0] == float("inf") else s[ans[1]:ans[2] + 1]

from collections import defaultdict, deque

def topo_order(n: int, edges: list[tuple[int,int]]) -> list[int] | None:
    graph = defaultdict(list)
    in_degree = [0] * n

    for a, b in edges:
        graph[a].append(b)
        in_degree[b] += 1

    queue = deque([i for i in range(n) if in_degree[i] == 0])
    topo_order = []

    while queue:
        if len(queue) > 1:
            return None  # Cycle detected
        node = queue.popleft()
        topo_order.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    return topo_order if len(topo_order) == n else None

